#
# Minimal parser/dumper for 11-byte frames:
# [4B picstop_low32][4B tof][1B channel][0x0D][0x0A] (little-endian)
#
# Produces a text file with one line per frame:
# offset  picstop_low32(hex)  picstop_low32(dec)  tof(hex)  tof(dec)  ch  ts_low32_only(s)

import argparse
import sys

FRAME_LEN = 11
CR = 0x0D
LF = 0x0A
PS_PER_TICK_DEFAULT = 100_000_000  # picoseconds per tick (100 microseconds)

def parse_args():
    p = argparse.ArgumentParser(description="Dump parsed frames to text for debugging.")
    p.add_argument("--infile", required=True, help="Captured binary file")
    p.add_argument("--outfile", required=True, help="Output text file")
    p.add_argument("--ps-per-tick", type=int, default=PS_PER_TICK_DEFAULT,
                   help="Picoseconds per tick (default 100,000,000)")
    return p.parse_args()

def main():
    args = parse_args()

    with open(args.infile, "rb") as f:
        data = f.read()

    out_lines = []
    i = 0
    n = len(data)
    crlf = bytes([CR, LF])

    def line_for(offset, frame):
        picstop_low = int.from_bytes(frame[0:4], "little", signed=False)
        tof = int.from_bytes(frame[4:8], "little", signed=False)
        ch = chr(frame[8])
        # Naive timestamp using only low32, no rollover
        ts_ps = (picstop_low * args.ps_per_tick) - tof
        ts_s = ts_ps / 1e12
        return (
            f"{offset:10d}  "
            f"0x{picstop_low:08X}  {picstop_low:10d}  "
            f"0x{tof:08X}  {tof:10d}  "
            f"{ch}  "
            f"{ts_s:.12f}"
        )

    while i + FRAME_LEN <= n:
        frame = data[i:i+FRAME_LEN]
        if frame[-2] == CR and frame[-1] == LF:
            out_lines.append(line_for(i, frame))
            i += FRAME_LEN
        else:
            # Search for next CRLF, then back up 9 bytes to get presumed frame start
            j = data.find(crlf, i + 1)
            if j == -1:
                break
            start = j - (FRAME_LEN - 2)
            if 0 <= start and start + FRAME_LEN <= n:
                frame = data[start:start+FRAME_LEN]
                if frame[-2] == CR and frame[-1] == LF:
                    out_lines.append(line_for(start, frame))
                    i = start + FRAME_LEN
                    continue
            i = j + 2

    with open(args.outfile, "w", encoding="utf-8", newline="\n") as out:
        out.write("# offset  picstop_low32(hex)  picstop_low32(dec)  tof(hex)  tof(dec)  ch  ts_low32_only(s)\n")
        for line in out_lines[:1000000]:  # cap just in case
            out.write(line + "\n")

    print(f"Wrote {len(out_lines)} frames to {args.outfile}", file=sys.stderr)
    print("Please share a small excerpt (e.g., first ~50 lines and around the jump).", file=sys.stderr)

if __name__ == "__main__":
    main()
